import React, { useEffect, useRef } from "react";
import { Html5QrcodeScanner } from "html5-qrcode";

function QRScanner() {

  const scannerRef = useRef(null);
  const lastScanRef = useRef(null);

  useEffect(() => {

    const scanner = new Html5QrcodeScanner(
      "reader",
      {
        fps: 20,
        qrbox: { width: 250, height: 250 }
      },
      false
    );

    scannerRef.current = scanner;

    scanner.render(

      async (decodedText) => {

        console.log("QR SCANNED:", decodedText);

        /* Prevent duplicate scan */
        if (lastScanRef.current === decodedText) {
          return;
        }

        lastScanRef.current = decodedText;

        try {

          const userId = decodedText;

          console.log("User ID:", userId);

          /* VERIFY USER */

          const verifyRes = await fetch(
            `http://localhost:5000/verify-user/${userId}`
          );

          const verifyData = await verifyRes.json();

          if (!verifyData.success) {
            alert("User Not Registered");
            lastScanRef.current = null;
            return;
          }

          alert("User Verified: " + verifyData.user.name);

          /* MARK ATTENDANCE */

          const attendanceRes = await fetch(
            `http://localhost:5000/mark-attendance/${userId}`,
            {
              method: "PUT"
            }
          );

          const attendanceData = await attendanceRes.json();

          if (attendanceData.success) {
            alert("Attendance Marked Successfully");
          } else {
            alert("Attendance Failed");
          }

        } catch (error) {

          console.log("Scanner Error:", error);
          alert("Server Error");

        }

        setTimeout(() => {
          lastScanRef.current = null;
        }, 3000);

      },

      (error) => {
        // ignore scan errors
      }

    );

    return () => {
      if (scannerRef.current) {
        scannerRef.current.clear().catch(() => {});
      }
    };

  }, []);

  return (
    <div style={{ textAlign: "center", marginTop: "30px" }}>
      <h2>Admin QR Scanner</h2>

      <div
        id="reader"
        style={{
          width: "400px",
          margin: "auto"
        }}
      ></div>
    </div>
  );

}

export default QRScanner;
